+/*
+ * Delegate for show and highlight found text in an item.
+ */
+
+#include "text_find_delegate.h"
+#include <ws_attributes.h>
+
+#include <QCheckBox>
+#include <QEvent>
+#include <QKeyEvent>
+#include <QLabel>
+#include <QLinearGradient>
+#include <QLineEdit>
